//! The rules store: the identity, the row types, and the CRUD the app and
// the CLI drive over [`AiStore`]. The `actions` payload rides as the
// caller's JSON text of the closed action set; the store round trips it
// untouched and the app layer rejects a payload outside the set loudly at
// parse.

use crate::store::AiStore;
use crate::AiStoreError;

/// The identity of one stored rule. Generated by the caller as a v4 UUID
/// (the [`CorrelationId`](crate::CorrelationId) spelling) so a rule exists
/// as data before it is stored, generation minting ids for unpersisted
/// rules among them.
#[derive(Debug, Clone, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
pub struct RuleId(String);

impl RuleId {
    /// Wraps an existing id string.
    pub fn new(value: String) -> Self {
        Self(value)
    }

    /// Generates a fresh rule id (a v4 UUID).
    pub fn generate() -> Self {
        Self(uuid::Uuid::new_v4().to_string())
    }

    /// The id string.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for RuleId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

/// One rule as the store reads it back: every column of the `rules` table,
/// `created_at` set by the store itself at insert.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct RuleRow {
    /// The rule's identity.
    pub id: RuleId,
    /// The rule's short name.
    pub name: String,
    /// The natural language condition sentence.
    pub condition: String,
    /// The actions payload: a JSON array of the closed action set's wire
    /// words.
    pub actions: String,
    /// Whether the incoming pass considers the rule.
    pub enabled: bool,
    /// The store's creation stamp (unix seconds).
    pub created_at: i64,
}

/// One rule to insert: every column the caller owns; the store stamps
/// `created_at` itself.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NewRule {
    /// The rule's identity.
    pub id: RuleId,
    /// The rule's short name.
    pub name: String,
    /// The natural language condition sentence.
    pub condition: String,
    /// The actions payload: a JSON array of the closed action set's wire
    /// words.
    pub actions: String,
    /// Whether the rule starts enabled.
    pub enabled: bool,
}

impl AiStore {
    /// Inserts one rule. A repeated id fails loudly on the primary key;
    /// the caller mints ids, so a collision is a caller bug, not a store
    /// state to paper over.
    ///
    /// # Errors
    /// Fails when the insert cannot run.
    pub fn create_rule(&self, rule: &NewRule) -> Result<(), AiStoreError> {
        let conn = self.lock();
        conn.execute(
            "INSERT INTO rules (
                 id, name, condition, actions, enabled, created_at
             ) VALUES (
                 ?1, ?2, ?3, ?4, ?5, strftime('%s','now')
             )",
            rusqlite::params![
                rule.id.as_str(),
                rule.name,
                rule.condition,
                rule.actions,
                rule.enabled,
            ],
        )
        .map_err(AiStoreError::Sqlite)?;
        Ok(())
    }

    /// Lists every rule in a stable order: creation time first, then name
    /// and id, so same-second inserts (a generated batch, one call) still
    /// list deterministically.
    ///
    /// # Errors
    /// Fails when the query cannot run.
    pub fn list_rules(&self) -> Result<Vec<RuleRow>, AiStoreError> {
        let conn = self.lock();
        let mut statement = conn
            .prepare(
                "SELECT id, name, condition, actions, enabled, created_at
                      FROM rules ORDER BY created_at, name, id",
            )
            .map_err(AiStoreError::Sqlite)?;
        let rows = statement
            .query_map([], |row| {
                Ok(RuleRow {
                    id: RuleId::new(row.get(0)?),
                    name: row.get(1)?,
                    condition: row.get(2)?,
                    actions: row.get(3)?,
                    enabled: row.get::<_, i64>(4)? != 0,
                    created_at: row.get(5)?,
                })
            })
            .map_err(AiStoreError::Sqlite)?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(AiStoreError::Sqlite)
    }

    /// Flips one rule's enabled flag. Returns whether any row changed:
    /// `false` names an id no rule carries, for the caller to report.
    ///
    /// # Errors
    /// Fails when the update cannot run.
    pub fn set_rule_enabled(&self, id: &RuleId, enabled: bool) -> Result<bool, AiStoreError> {
        let conn = self.lock();
        conn.execute(
            "UPDATE rules SET enabled = ?2 WHERE id = ?1",
            rusqlite::params![id.as_str(), enabled],
        )
        .map(|changed| changed > 0)
        .map_err(AiStoreError::Sqlite)
    }

    /// Deletes one rule. Returns whether any row went: `false` names an id
    /// no rule carried, for the caller to report.
    ///
    /// # Errors
    /// Fails when the delete cannot run.
    pub fn delete_rule(&self, id: &RuleId) -> Result<bool, AiStoreError> {
        let conn = self.lock();
        conn.execute(
            "DELETE FROM rules WHERE id = ?1",
            rusqlite::params![id.as_str()],
        )
        .map(|changed| changed > 0)
        .map_err(AiStoreError::Sqlite)
    }
}
